\ir _helpers/auth_session.sql
\ir _helpers/commercial_terms.sql
begin;
select no_plan();
-- Fresh test offering isolates engine invariants from installed adapters and preview prices.
insert into public.commercial_offerings(code,name,description) values('synthetic_engine_fixture','Synthetic engine fixture','Rollback-only independent offering');
insert into auth.users(id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select ('73000000-0000-0000-0000-'||lpad(i::text,12,'0'))::uuid,'authenticated','authenticated','commercial-'||i||'@example.invalid','x',now(),'{}','{}',now(),now() from generate_series(1,3)i;
update public.users set role='superadmin' where id='73000000-0000-0000-0000-000000000003';
create function pg_temp.commercial_admin() returns void language plpgsql as $$begin
 perform pg_temp.set_test_user('73000000-0000-0000-0000-000000000003',true);
 perform set_config('request.jwt.claims',(current_setting('request.jwt.claims')::jsonb||jsonb_build_object('amr',jsonb_build_array(jsonb_build_object('method','password','timestamp',extract(epoch from clock_timestamp())::bigint))))::text,true);
end$$;
select pg_temp.commercial_admin();
set local role authenticated;
select is((select count(*)::integer from jsonb_array_elements(public.admin_commercial_catalog()->'items') x where x->>'code' in('ad_community','ad_home','ad_network','post_boost','community_boost','product_storefront','professional_profile','establishment_profile')),8,'central catalog has eight services without invented prices');
select throws_ok($$select public.admin_publish_commercial_price('synthetic_engine_fixture','0',1,7,null,0,gen_random_uuid(),'Synthetic price',true)$$,'INVALID_COMMERCIAL_PRICE','zero price fails');
select throws_ok($$select public.admin_publish_commercial_price('synthetic_engine_fixture','2147483647',1,2,null,0,gen_random_uuid(),'Synthetic price',true)$$,'INVALID_COMMERCIAL_PRICE','overflow fails');
select throws_ok($$select public.admin_publish_commercial_price('synthetic_engine_fixture','2',0,2,null,0,gen_random_uuid(),'Synthetic price',true)$$,'INVALID_COMMERCIAL_PRICE','invalid limits fail');
select throws_ok($$select public.admin_publish_commercial_price('synthetic_engine_fixture','2',1,30,null,0,gen_random_uuid(),'Synthetic price',false)$$,'INVALID_COMMERCIAL_PRICE','explicit admin confirmation required');
select public.admin_publish_commercial_price('synthetic_engine_fixture','2',1,30,null,0,'73100000-0000-0000-0000-000000000001','Synthetic price only',true);
select is(public.admin_publish_commercial_price('synthetic_engine_fixture','2',1,30,null,0,'73100000-0000-0000-0000-000000000001','Synthetic price only',true)->>'revision','1','admin retry returns same version');
select throws_ok($$select public.admin_publish_commercial_price('synthetic_engine_fixture','3',1,30,null,1,'73100000-0000-0000-0000-000000000001','Synthetic price only',true)$$,'IDEMPOTENCY_CONFLICT','admin request cannot change payload');
select throws_ok($$select public.admin_set_commercial_sales('synthetic_engine_fixture',true,1,gen_random_uuid(),'Synthetic enable',true)$$,'COMMERCIAL_INTEGRATION_UNAVAILABLE','no live adapter can sell');
reset role;
update public.commercial_offerings set integration_ready=true where code='synthetic_engine_fixture';
select public.admin_set_commercial_sales('synthetic_engine_fixture',true,1,gen_random_uuid(),'Synthetic enable',true);
insert into private.commercial_resources(id,offering_code,owner_user_id,content_revision,approved_revision,moderation_state)
values('73200000-0000-0000-0000-000000000001','synthetic_engine_fixture','73000000-0000-0000-0000-000000000001',1,1,'approved'),
('73200000-0000-0000-0000-000000000002','synthetic_engine_fixture','73000000-0000-0000-0000-000000000001',1,null,'submitted');
select public._wallet_credit_cash('73000000-0000-0000-0000-000000000001',100);
select public._ledger_record('73000000-0000-0000-0000-000000000001','synthetic-seed','cash','credit',100,'synthetic','fixture','commercial');
select pg_temp.set_test_user('73000000-0000-0000-0000-000000000001',true);
create temp table results(name text primary key,value jsonb); grant all on results to authenticated;
set local role authenticated;
select throws_ok($$select public.admin_commercial_catalog()$$,'42501','PERMISSION_DENIED','ordinary user cannot read admin catalog');
select pg_temp.publish_test_commercial_terms(); -- 20261212000002: termos comerciais sintéticos publicados
select throws_ok($$select public.quote_commercial_order('73200000-0000-0000-0000-000000000001','0',gen_random_uuid())$$,'INVALID_DURATION','zero duration fails');
select throws_ok($$select public.quote_commercial_order('73200000-0000-0000-0000-000000000001','1.5',gen_random_uuid())$$,'INVALID_DURATION','fractional duration fails');
select throws_ok($$select public.quote_commercial_order('73200000-0000-0000-0000-000000000001','999999999999999999',gen_random_uuid())$$,'INVALID_DURATION','oversized duration fails before cast');
select throws_ok($$select public.quote_commercial_order('73200000-0000-0000-0000-000000000002','1',gen_random_uuid())$$,'RESOURCE_NOT_ELIGIBLE','awaiting approval is never charged');
select throws_ok($$select public.quote_commercial_order(gen_random_uuid(),'1',gen_random_uuid())$$,'RESOURCE_NOT_ELIGIBLE','nonexistent resource cannot buy rights');
insert into results values('q',public.quote_commercial_order('73200000-0000-0000-0000-000000000001','7','73300000-0000-0000-0000-000000000001'));
select is((select value->>'totalCash' from results where name='q'),'14','server computes exact total as integer string');
select is(public.quote_commercial_order('73200000-0000-0000-0000-000000000001','7','73300000-0000-0000-0000-000000000001')->>'id',(select value->>'id' from results where name='q'),'quote replay returns same order');
select throws_ok($$select public.quote_commercial_order('73200000-0000-0000-0000-000000000001','8','73300000-0000-0000-0000-000000000001')$$,'IDEMPOTENCY_CONFLICT','request cannot mutate duration');
select throws_ok($$update public.commercial_orders set total_cash=1$$,'42501',null,'direct financial write denied');
select throws_ok($$update public.visibility_entitlements set expires_at=now()+interval '1 year'$$,'42501',null,'direct expiry mutation denied');
select throws_ok($$select pg_temp.confirm_with_terms((select(value->>'id')::uuid from results where name='q'),false)$$,'CONFIRMATION_REQUIRED','explicit buyer confirmation required');
reset role;
select pg_temp.commercial_admin();
select public.admin_publish_commercial_price('synthetic_engine_fixture','3',1,30,null,2,gen_random_uuid(),'Synthetic price increased',true);
select pg_temp.set_test_user('73000000-0000-0000-0000-000000000001',true);
set local role authenticated;
insert into results values('paid',pg_temp.confirm_with_terms((select(value->>'id')::uuid from results where name='q'),true));
select is((select value->>'totalCash' from results where name='paid'),'14','old quote survives price publication');
select is(pg_temp.confirm_with_terms((select(value->>'id')::uuid from results where name='q'),true),(select value from results where name='paid'),'confirmation replay has no new debit');
reset role;
select is((select cash_balance from public.wallets where user_id='73000000-0000-0000-0000-000000000001'),86,'one exact debit');
select is((select count(*)::integer from public.economy_transactions where reference_type='commercial_order' and user_id='73000000-0000-0000-0000-000000000001'),1,'one unique ledger entry');
select is((select extract(epoch from expires_at-starts_at)::bigint from public.visibility_entitlements where resource_id='73200000-0000-0000-0000-000000000001'),604800::bigint,'seven days are exactly 168 hours');
select ok(private.commercial_resource_visible('73200000-0000-0000-0000-000000000001'),'approved paid resource is eligible');
insert into public.account_restrictions(user_id,action,until) values('73000000-0000-0000-0000-000000000001','temporary_suspension',clock_timestamp()+interval '1 hour');
select ok(not private.commercial_resource_visible('73200000-0000-0000-0000-000000000001'),'owner restriction hides even a paid approved resource');
delete from public.account_restrictions where user_id='73000000-0000-0000-0000-000000000001';
select pg_temp.commercial_admin();
select public.admin_set_commercial_sales('synthetic_engine_fixture',false,3,gen_random_uuid(),'Synthetic pause sales',true);
select ok(private.commercial_resource_visible('73200000-0000-0000-0000-000000000001'),'pausing sales preserves acquired right');
select public.admin_set_commercial_sales('synthetic_engine_fixture',true,4,gen_random_uuid(),'Synthetic resume sales',true);
select pg_temp.set_test_user('73000000-0000-0000-0000-000000000001',true);
set local role authenticated;
insert into results values('renew',public.quote_commercial_order('73200000-0000-0000-0000-000000000001','2',gen_random_uuid()));
select is((select value->>'totalCash' from results where name='renew'),'6','renewal uses current price');
select pg_temp.confirm_with_terms((select(value->>'id')::uuid from results where name='renew'),true);
reset role;
select is((select extract(epoch from expires_at-starts_at)::bigint from public.visibility_entitlements where resource_id='73200000-0000-0000-0000-000000000001'),777600::bigint,'early renewal extends remaining period by exact 48 hours');
-- Artificial time travel changes only disposable fixture, never production mechanism.
update public.visibility_entitlements set starts_at=clock_timestamp()-interval '10 days',expires_at=clock_timestamp()-interval '1 second' where resource_id='73200000-0000-0000-0000-000000000001';
select ok(not private.commercial_resource_visible('73200000-0000-0000-0000-000000000001'),'expired right denies access without cron');
set local role authenticated;
insert into results values('late',public.quote_commercial_order('73200000-0000-0000-0000-000000000001','1',gen_random_uuid()));
select pg_temp.confirm_with_terms((select(value->>'id')::uuid from results where name='late'),true);
reset role;
select is((select extract(epoch from expires_at-starts_at)::bigint from public.visibility_entitlements where resource_id='73200000-0000-0000-0000-000000000001'),86400::bigint,'late renewal begins a new 24 hour period');
-- Server time is authoritative; expired quotes and insufficient funds cannot debit.
insert into public.commercial_orders(payer_user_id,request_id,resource_id,offering_code,price_version_id,content_revision,duration_days,unit_price_cash,total_cash,created_at,quote_expires_at)
select '73000000-0000-0000-0000-000000000001',gen_random_uuid(),'73200000-0000-0000-0000-000000000001','synthetic_engine_fixture',id,1,1,3,3,now()-interval '10 minutes',now()-interval '5 minutes' from public.commercial_price_versions where offering_code='synthetic_engine_fixture' and revision=3;
set local role authenticated;
select throws_ok($$select pg_temp.confirm_with_terms((select id from public.commercial_orders where quote_expires_at<now() limit 1),true)$$,'QUOTE_EXPIRED','expired quote cannot debit');
insert into results values('insufficient',public.quote_commercial_order('73200000-0000-0000-0000-000000000001','30',gen_random_uuid()));
select throws_ok($$select pg_temp.confirm_with_terms((select(value->>'id')::uuid from results where name='insufficient'),true)$$,'Saldo de EvoCash insuficiente.','insufficient balance preserves order and right');
reset role;
-- Approved version changes after quote must fail before debit.
set local role authenticated;
insert into results values('stale',public.quote_commercial_order('73200000-0000-0000-0000-000000000001','1',gen_random_uuid()));
reset role;
update private.commercial_resources set content_revision=2,approved_revision=2 where id='73200000-0000-0000-0000-000000000001';
set local role authenticated;
select throws_ok($$select pg_temp.confirm_with_terms((select(value->>'id')::uuid from results where name='stale'),true)$$,'RESOURCE_NOT_ELIGIBLE','approved revision rechecked inside financial transaction');
reset role;
update private.commercial_resources set moderation_state='suspended' where id='73200000-0000-0000-0000-000000000001';
select ok(not private.commercial_resource_visible('73200000-0000-0000-0000-000000000001'),'content suspension overrides payment');
set local role authenticated;
select throws_ok($$select public.quote_commercial_order('73200000-0000-0000-0000-000000000001','1',gen_random_uuid())$$,'RESOURCE_NOT_ELIGIBLE','payment cannot reactivate suspended content');
reset role;
update private.commercial_resources set moderation_state='approved' where id='73200000-0000-0000-0000-000000000001';
select pg_temp.commercial_admin();
select public.admin_set_commercial_entitlement((select id from public.visibility_entitlements where resource_id='73200000-0000-0000-0000-000000000001'),'suspended',3,gen_random_uuid(),'Synthetic security suspension',true);
select ok(not private.commercial_resource_visible('73200000-0000-0000-0000-000000000001'),'admin suspension stops eligibility immediately');
select pg_temp.set_test_user('73000000-0000-0000-0000-000000000001',true);
set local role authenticated;
select throws_ok($$select public.quote_commercial_order('73200000-0000-0000-0000-000000000001','1',gen_random_uuid())$$,'ENTITLEMENT_BLOCKED','renewal cannot override suspended right');
reset role;
select pg_temp.commercial_admin();
select public.admin_set_commercial_entitlement((select id from public.visibility_entitlements where resource_id='73200000-0000-0000-0000-000000000001'),'enabled',4,gen_random_uuid(),'Synthetic resume approved right',true);
-- Inject an error AFTER wallet, ledger and order writes to prove rollback indivisibility.
insert into results values('right_before_fault',(select to_jsonb(e) from public.visibility_entitlements e where resource_id='73200000-0000-0000-0000-000000000001'));
create function pg_temp.fail_grant() returns trigger language plpgsql as $$begin raise exception 'SYNTHETIC_GRANT_FAILURE'; end$$;
create trigger commercial_test_fault before update on public.visibility_entitlements for each row execute function pg_temp.fail_grant();
select pg_temp.set_test_user('73000000-0000-0000-0000-000000000001',true);
set local role authenticated;
insert into results values('fault',public.quote_commercial_order('73200000-0000-0000-0000-000000000001','1',gen_random_uuid()));
select throws_ok($$select pg_temp.confirm_with_terms((select(value->>'id')::uuid from results where name='fault'),true)$$,'SYNTHETIC_GRANT_FAILURE','fault after debit rolls back entire transaction');
reset role;
select is((select cash_balance from public.wallets where user_id='73000000-0000-0000-0000-000000000001'),77,'fault preserves balance');
select is((select count(*)::integer from public.economy_transactions where reference_type='commercial_order' and user_id='73000000-0000-0000-0000-000000000001'),3,'fault preserves ledger');
select is((select status from public.commercial_orders where id=(select(value->>'id')::uuid from results where name='fault')),'quoted','fault leaves order unfulfilled');
select is((select to_jsonb(e) from public.visibility_entitlements e where resource_id='73200000-0000-0000-0000-000000000001'),(select value from results where name='right_before_fault'),'fault preserves entitlement dates and revision');
select is((select count(*)::integer from public.commercial_order_events where order_id=(select(value->>'id')::uuid from results where name='fault') and action in('fulfilled','renewed')),0,'fault cannot record a fulfillment event');
drop trigger commercial_test_fault on public.visibility_entitlements;
select pg_temp.set_test_user('73000000-0000-0000-0000-000000000002',true);
set local role authenticated;
select is((select count(*)::integer from public.commercial_orders),0,'RLS isolates orders');
select throws_ok($$select pg_temp.confirm_with_terms((select(value->>'id')::uuid from results where name='q'),true)$$,'ORDER_NOT_FOUND','cannot confirm another wallet order');
select throws_ok($$select public.quote_commercial_order('73200000-0000-0000-0000-000000000001','1',gen_random_uuid())$$,'RESOURCE_NOT_ELIGIBLE','cannot buy another owner resource');
reset role;
select pg_temp.set_test_user('73000000-0000-0000-0000-000000000001',true);
update public.users set account_status='disabled' where id='73000000-0000-0000-0000-000000000001';
set local role authenticated;
select throws_ok($$select pg_temp.confirm_with_terms((select(value->>'id')::uuid from results where name='fault'),true)$$,'42501','APP_ACCESS_DENIED','blocked user cannot spend');
reset role;
update public.users set account_status='active' where id='73000000-0000-0000-0000-000000000001';
select pg_temp.revoke_test_session('73000000-0000-0000-0000-000000000001');
set local role authenticated;
select throws_ok($$select pg_temp.confirm_with_terms((select(value->>'id')::uuid from results where name='q'),true)$$,'42501','APP_ACCESS_DENIED','revoked session cannot replay');
reset role;
select pg_temp.commercial_admin();
select public.admin_reverse_commercial_order((select(value->>'id')::uuid from results where name='late'),'73400000-0000-0000-0000-000000000001','Synthetic refund last contract',true);
select is(public.admin_reverse_commercial_order((select(value->>'id')::uuid from results where name='late'),'73400000-0000-0000-0000-000000000001','Synthetic refund last contract',true)->>'status','reversed','refund replay is idempotent');
select is((select cash_balance from public.wallets where user_id='73000000-0000-0000-0000-000000000001'),80,'refund restores original exact debit');
select ok(not private.commercial_resource_visible('73200000-0000-0000-0000-000000000001'),'refunded new period is revoked');
select throws_ok($$update public.commercial_price_versions set unit_price_cash=1$$,'42501','COMMERCIAL_HISTORY_IMMUTABLE','published price history immutable');
select throws_ok($$delete from public.commercial_order_events$$,'42501','COMMERCIAL_HISTORY_IMMUTABLE','audit is append-only');
select ok(not has_function_privilege('service_role','public.confirm_commercial_order(uuid,boolean)','execute'),'service role cannot debit arbitrary caller wallet');
select ok(not has_function_privilege('authenticated','private.commercial_resource_visible(uuid)','execute'),'private eligibility is no public resource oracle');
select ok(not has_table_privilege('authenticated','private.commercial_resources','insert'),'client cannot register arbitrary resource or approve it');
select * from finish();
rollback;
